// Mappning från journalsystemets proprietära patient-JSON till en FHIR Patient enligt profilen EducationPatient.
// Syntax: källa -> mål "regelnamn";   (läs mer: https://hl7.org/fhir/R4/mapping-language.html)

map "http://example.org/fhir/education/StructureMap/JournalPatientTillFhir" = "JournalPatientTillFhir"

// Journalsystemets könskoder översätts till FHIR:s koder med en inbäddad ConceptMap.
conceptmap "kon" {
  prefix s = "http://example.org/fhir/education/journalsystem/kon"
  prefix t = "http://hl7.org/fhir/administrative-gender"

  s:M == t:male
  s:K == t:female
}

uses "http://example.org/fhir/education/journalsystem/StructureDefinition/JournalPatient" alias JournalPatient as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group JournalPatientTillFhir(source src : JournalPatient, target tgt : Patient) {
  // Profilen som resultatet ska följa
  src -> tgt.meta as meta, meta.profile = 'http://example.org/fhir/education/kursig/StructureDefinition/EducationPatient' "profil";

  // Personnumret blir identifierare. (Resursens logiska id sätts av fasaden, inte av mappningen.)
  src.personnummer as pnr -> tgt.identifier as ident, ident.system = 'http://electronichealth.se/identifier/personnummer', ident.value = pnr "personnummer";

  // Ett namn med efternamn och förnamn (inre regler körs inom samma HumanName)
  src -> tgt.name as namn, namn.use = 'official' then {
    src.efternamn as efternamn -> namn.family = efternamn "efternamn";
    src.fornamn as fornamn -> namn.given = fornamn "fornamn";
  } "namn";

  src.kon as kon -> tgt.gender = translate(kon, '#kon', 'code') "kon";
  src.fodelsedatum as fd -> tgt.birthDate = fd "fodelsedatum";

  // ÖVNING 5.2: Journalsystemet har ett telefonnummer (src.telefon) som inte mappas ännu.
  // Lägg till en regel här som mappar det till Patient.telecom (system = phone).
}
